policies.text:
permit (
  principal,
  action in [
    WhiteTower::Action::"tool.expose", WhiteTower::Action::"tool.invoke", WhiteTower::Action::"tool.result",
    WhiteTower::Action::"model.invoke", WhiteTower::Action::"model.result"
  ],
  resource
);

permit (
  principal,
  action in [
    WhiteTower::Action::"tool.expose", WhiteTower::Action::"tool.invoke", WhiteTower::Action::"tool.result",
    WhiteTower::Action::"model.invoke", WhiteTower::Action::"model.result"
  ],
  resource
);

forbid (principal, action == WhiteTower::Action::"tool.invoke", resource == WhiteTower::Tool::"agent/send_email")
when {
  context has args && context.args has "agent/send_email" && context.args["agent/send_email"] has "to:email_domain" &&
  context.args["agent/send_email"]["to:email_domain"] == "competitor.example"
};

